steps.script:
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var ph = H.phase()
if H.window_id() != "unit_selected_to_shoot":
	return true
var w = ph.get_pending_stratagem_window()
ph.execute_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": "unit_selected_to_shoot"})
if H.window_id() == "unit_has_shot":
	return true
return H.shoot(1, "U_IMPULSOR_A", "U_DEFF_DREAD_A", "storm_bolter", 5)

GameState.state.units["U_INTERCESSOR_SQUAD_A"].flags["disembarked_this_turn"] = true
var m = RulesEngine.ork11e_ab_mods(GameState.state.units["U_INTERCESSOR_SQUAD_A"], GameState.state.units["U_DEFF_DREAD_A"], {"name": "x"}, false, GameState.state)
return int(m.get("sustained", 0))

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sm11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
